export const PY_SHO = "\"\"\"\nWeek 3 - Quantum Harmonic Oscillator\nPhysical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n\nSolves the SHO via Hermite polynomials:\n  psi_n(y) = (1/pi)^(1/4) / sqrt(2^n n!) * H_n(y) * exp(-y^2/2),\n  y = sqrt(m*omega/hbar) x,  E_n = (n + 1/2) hbar*omega\nVerifies: Hermite orthogonality, normalization, virial theorem,\nand the classically forbidden (\"tunneling\") probability.\n\"\"\"\nimport numpy as np\nfrom math import factorial, pi, sqrt\n\ntrapz = getattr(np, \"trapezoid\", getattr(np, \"trapz\", None))  # numpy 1.x/2.x compat\n\ndef hermite(n, y):\n    \"\"\"Physicists' Hermite polynomial H_n(y) via H_{n+1} = 2y H_n - 2n H_{n-1}.\"\"\"\n    if n == 0: return np.ones_like(y)\n    if n == 1: return 2.0 * y\n    Hm, Hc = np.ones_like(y), 2.0 * y\n    for k in range(1, n):\n        Hm, Hc = Hc, 2.0 * y * Hc - 2.0 * k * Hm\n    return Hc\n\ndef psi(n, y):\n    \"\"\"Normalized SHO eigenfunction in dimensionless y (hbar = m = omega = 1).\"\"\"\n    norm = 1.0 / sqrt(2.0**n * factorial(n)) * (1.0 / pi)**0.25\n    return norm * hermite(n, y) * np.exp(-y**2 / 2.0)\n\nif __name__ == \"__main__\":\n    y = np.linspace(-12, 12, 240001)\n\n    # 1) Hermite orthogonality: int e^{-y^2} H_m H_n dy = 2^n n! sqrt(pi) delta_mn\n    print(\"Hermite orthogonality (integral / 2^n n! sqrt(pi)):\")\n    for m in range(4):\n        row = [trapz(np.exp(-y**2) * hermite(m, y) * hermite(n, y), y)\n               / (2.0**n * factorial(n) * sqrt(pi)) for n in range(4)]\n        print(\"  \", [\"%+.6f\" % v for v in row])\n\n    # 2) Normalization of psi_n\n    for n in [0, 1, 5, 10]:\n        print(f\"<psi_{n}|psi_{n}> = {trapz(psi(n, y)**2, y):.6f}\")\n\n    # 3) Virial theorem: <V> = E_n/2 (units of hbar*omega)\n    for n in [0, 3]:\n        V = trapz(0.5 * y**2 * psi(n, y)**2, y)\n        print(f\"n={n}: <V> = {V:.5f}  (E_n/2 = {(n + 0.5) / 2:.5f})\")\n\n    # 4) Classical turning point y_tp = sqrt(2n+1) & forbidden-region probability\n    for n in [0, 1, 5]:\n        ytp = sqrt(2 * n + 1.0)\n        Pout = trapz(np.where(np.abs(y) > ytp, psi(n, y)**2, 0.0), y)\n        print(f\"n={n}: y_tp = {ytp:.4f}, P(classically forbidden) = {Pout:.4f}\")\n";

export const ML_SHO = "%% Week 3 - Quantum Harmonic Oscillator (Hermite polynomials)\n%  Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n%  psi_n(y) = (1/pi)^(1/4)/sqrt(2^n n!) H_n(y) exp(-y^2/2), E_n = (n+1/2) hbar*w\nclear; clc;\n\ny = linspace(-12, 12, 240001);\n\n% Hermite orthogonality: int e^{-y^2} H_m H_n dy = 2^n n! sqrt(pi) delta_mn\nfprintf('Hermite orthogonality (normalized):\\n');\nfor m = 0:3\n    row = zeros(1,4);\n    for n = 0:3\n        I = trapz(y, exp(-y.^2).*hermiteH_rec(m,y).*hermiteH_rec(n,y));\n        row(n+1) = I/(2^n*factorial(n)*sqrt(pi));\n    end\n    fprintf('  %+.6f %+.6f %+.6f %+.6f\\n', row);\nend\n\n% Normalization & virial theorem\nfor n = [0 1 5 10]\n    fprintf('<psi_%d|psi_%d> = %.6f\\n', n, n, trapz(y, psiSHO(n,y).^2));\nend\nfor n = [0 3]\n    V = trapz(y, 0.5*y.^2.*psiSHO(n,y).^2);\n    fprintf('n=%d: <V> = %.5f (E_n/2 = %.5f)\\n', n, V, (n+0.5)/2);\nend\n\n% Classically forbidden probability beyond y_tp = sqrt(2n+1)\nfor n = [0 1 5]\n    ytp = sqrt(2*n+1);\n    Pout = trapz(y, (abs(y)>ytp).*psiSHO(n,y).^2);\n    fprintf('n=%d: y_tp = %.4f, P(forbidden) = %.4f\\n', n, ytp, Pout);\nend\n\n% Plot the first 4 eigenfunctions offset by their energies\nfigure; hold on;\nyy = linspace(-5,5,801);\nplot(yy, 0.5*yy.^2, 'k-', 'LineWidth', 1.2);\nfor n = 0:3\n    plot(yy, (n+0.5) + 0.6*psiSHO(n,yy), 'LineWidth', 1.4);\nend\nxlabel('y'); ylabel('E/\\hbar\\omega'); title('SHO eigenfunctions on the potential');\ngrid on; ylim([0 4.5]);\n\nfunction H = hermiteH_rec(n, y)\n% Physicists' Hermite polynomial via H_{n+1} = 2y H_n - 2n H_{n-1}\n    if n == 0, H = ones(size(y)); return; end\n    if n == 1, H = 2*y; return; end\n    Hm = ones(size(y)); Hc = 2*y;\n    for k = 1:n-1\n        Hn = 2*y.*Hc - 2*k*Hm; Hm = Hc; Hc = Hn;\n    end\n    H = Hc;\nend\n\nfunction p = psiSHO(n, y)\n% Normalized SHO eigenfunction (hbar = m = omega = 1)\n    p = 1/sqrt(2^n*factorial(n))*(1/pi)^0.25*hermiteH_rec(n,y).*exp(-y.^2/2);\nend\n";

export const JL_SHO = "# Week 3 - Quantum Harmonic Oscillator (Hermite polynomials)\n# Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n# psi_n(y) = (1/pi)^(1/4)/sqrt(2^n n!) H_n(y) exp(-y^2/2), E_n = (n+1/2) hbar*w\nusing Printf\n\n\"Physicists' Hermite polynomial via H_{n+1} = 2y H_n - 2n H_{n-1}\"\nfunction hermiteH(n::Int, y)\n    n == 0 && return one.(y)\n    n == 1 && return 2 .* y\n    Hm, Hc = one.(y), 2 .* y\n    for k in 1:n-1\n        Hm, Hc = Hc, 2 .* y .* Hc .- 2k .* Hm\n    end\n    return Hc\nend\n\n\"Normalized SHO eigenfunction (hbar = m = omega = 1)\"\npsiSHO(n, y) = 1 / sqrt(2.0^n * factorial(big(n))) * (1 / pi)^0.25 .* hermiteH(n, y) .* exp.(-y .^ 2 ./ 2)\n\ntrapz(x, f) = sum((f[1:end-1] .+ f[2:end]) .* diff(x)) / 2\n\ny = range(-12, 12; length = 240001) |> collect\n\n# 1) Hermite orthogonality\nprintln(\"Hermite orthogonality (normalized):\")\nfor m in 0:3\n    row = [trapz(y, exp.(-y .^ 2) .* hermiteH(m, y) .* hermiteH(n, y)) /\n           (2.0^n * factorial(n) * sqrt(pi)) for n in 0:3]\n    @printf(\"  %+.6f %+.6f %+.6f %+.6f\\n\", row...)\nend\n\n# 2) Normalization & virial theorem\nfor n in (0, 1, 5, 10)\n    @printf(\"<psi_%d|psi_%d> = %.6f\\n\", n, n, trapz(y, psiSHO(n, y) .^ 2))\nend\nfor n in (0, 3)\n    V = trapz(y, 0.5 .* y .^ 2 .* psiSHO(n, y) .^ 2)\n    @printf(\"n=%d: <V> = %.5f (E_n/2 = %.5f)\\n\", n, V, (n + 0.5) / 2)\nend\n\n# 3) Classically forbidden probability beyond y_tp = sqrt(2n+1)\nfor n in (0, 1, 5)\n    ytp = sqrt(2n + 1)\n    Pout = trapz(y, (abs.(y) .> ytp) .* psiSHO(n, y) .^ 2)\n    @printf(\"n=%d: y_tp = %.4f, P(forbidden) = %.4f\\n\", n, ytp, Pout)\nend\n";

export const CPP_SHO = "// Week 3 - Quantum Harmonic Oscillator (Hermite polynomials)\n// Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n// psi_n(y) = (1/pi)^(1/4)/sqrt(2^n n!) H_n(y) exp(-y^2/2), E_n = (n+1/2) hbar*w\n// Build: g++ -O2 -std=c++17 wk03_sho.cpp -o wk03_sho\n#include <cstdio>\n#include <cmath>\n#include <vector>\n\ndouble hermiteH(int n, double y) {           // H_{n+1} = 2y H_n - 2n H_{n-1}\n    if (n == 0) return 1.0;\n    if (n == 1) return 2.0 * y;\n    double Hm = 1.0, Hc = 2.0 * y;\n    for (int k = 1; k < n; ++k) {\n        double Hn = 2.0 * y * Hc - 2.0 * k * Hm;\n        Hm = Hc; Hc = Hn;\n    }\n    return Hc;\n}\n\ndouble factorial(int n) { double f = 1; for (int i = 2; i <= n; ++i) f *= i; return f; }\n\ndouble psiSHO(int n, double y) {             // hbar = m = omega = 1\n    double norm = 1.0 / std::sqrt(std::pow(2.0, n) * factorial(n)) * std::pow(M_PI, -0.25);\n    return norm * hermiteH(n, y) * std::exp(-y * y / 2.0);\n}\n\n// trapezoid rule on a uniform grid\ntemplate <typename F>\ndouble integrate(F f, double a, double b, int N) {\n    double h = (b - a) / N, s = 0.5 * (f(a) + f(b));\n    for (int i = 1; i < N; ++i) s += f(a + i * h);\n    return s * h;\n}\n\nint main() {\n    const double A = 12.0; const int NG = 240000;\n\n    // 1) Hermite orthogonality: int e^{-y^2} H_m H_n dy = 2^n n! sqrt(pi) delta_mn\n    std::printf(\"Hermite orthogonality (normalized):\\n\");\n    for (int m = 0; m < 4; ++m) {\n        for (int n = 0; n < 4; ++n) {\n            double I = integrate([&](double y) {\n                return std::exp(-y * y) * hermiteH(m, y) * hermiteH(n, y); }, -A, A, NG);\n            std::printf(\" %+.6f\", I / (std::pow(2.0, n) * factorial(n) * std::sqrt(M_PI)));\n        }\n        std::printf(\"\\n\");\n    }\n\n    // 2) Normalization & virial theorem\n    for (int n : {0, 1, 5, 10}) {\n        double I = integrate([&](double y) { double p = psiSHO(n, y); return p * p; }, -A, A, NG);\n        std::printf(\"<psi_%d|psi_%d> = %.6f\\n\", n, n, I);\n    }\n    for (int n : {0, 3}) {\n        double V = integrate([&](double y) { double p = psiSHO(n, y); return 0.5 * y * y * p * p; }, -A, A, NG);\n        std::printf(\"n=%d: <V> = %.5f (E_n/2 = %.5f)\\n\", n, V, (n + 0.5) / 2.0);\n    }\n\n    // 3) Classically forbidden probability beyond y_tp = sqrt(2n+1)\n    for (int n : {0, 1, 5}) {\n        double ytp = std::sqrt(2.0 * n + 1.0);\n        double P = 2.0 * integrate([&](double y) { double p = psiSHO(n, y); return p * p; }, ytp, A, NG);\n        std::printf(\"n=%d: y_tp = %.4f, P(forbidden) = %.4f\\n\", n, ytp, P);\n    }\n    return 0;\n}\n";

export const PY_LADDER = "\"\"\"\nWeek 3 - Creation & Annihilation (Ladder) Operators for the SHO\nPhysical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n\nBuilds a, a^dagger, X, P, H as matrices in the number basis |n> and verifies:\n  a|n> = sqrt(n)|n-1>,  a^dag|n> = sqrt(n+1)|n+1>,  [a, a^dag] = 1,\n  H = hbar*omega (a^dag a + 1/2) with eigenvalues (n + 1/2) hbar*omega,\n  [X, P] = i*hbar  (hbar = m = omega = 1).\nNote: in a truncated N x N basis the identities hold exactly except\nin the last row/column (truncation edge) - a nice teaching point.\n\"\"\"\nimport numpy as np\n\ndef ladder_ops(N):\n    \"\"\"Return (a, adag) as N x N matrices in the number basis.\"\"\"\n    a = np.zeros((N, N))\n    for n in range(1, N):\n        a[n - 1, n] = np.sqrt(n)          # <n-1| a |n> = sqrt(n)\n    return a, a.T.copy()\n\nif __name__ == \"__main__\":\n    N = 30\n    a, ad = ladder_ops(N)\n\n    # 1) [a, a^dag] = 1 (exact except the (N-1, N-1) truncation corner)\n    comm = a @ ad - ad @ a\n    I = np.eye(N)\n    err_bulk = np.max(np.abs((comm - I)[:N - 1, :N - 1]))\n    print(f\"[a, a^dag] = 1: max bulk error = {err_bulk:.2e}, corner value = {comm[-1, -1]:+.1f}\")\n\n    # 2) Number operator & Hamiltonian\n    H = ad @ a + 0.5 * I\n    evals = np.sort(np.linalg.eigvalsh(H))[:6]\n    print(\"First 6 eigenvalues of H/hbar*omega:\", np.round(evals, 6))\n\n    # 3) X, P from ladder operators; check [X, P] = i (bulk)\n    X = (a + ad) / np.sqrt(2.0)\n    P = 1j * (ad - a) / np.sqrt(2.0)\n    commXP = X @ P - P @ X\n    print(f\"Im<0|[X,P]|0> = {commXP[0, 0].imag:.6f} (expect 1)\")\n    print(f\"max bulk |[X,P] - i| = {np.max(np.abs((commXP - 1j * I)[:N-1, :N-1])):.2e}\")\n\n    # 4) Matrix elements: <n-1|a|n> = sqrt(n)\n    print(\"a matrix elements <n-1|a|n>:\", [f\"{a[n-1, n]:.4f}\" for n in range(1, 6)],\n          \"vs sqrt(n):\", [f\"{np.sqrt(n):.4f}\" for n in range(1, 6)])\n\n    # 5) Uncertainty product in state |n>: sigma_x * sigma_p = (n + 1/2) hbar\n    for n in [0, 1, 4]:\n        v = np.zeros(N); v[n] = 1.0\n        sx = np.sqrt(v @ (X @ X) @ v - (v @ X @ v)**2)\n        sp = np.sqrt(np.real(v @ (P @ P) @ v - (v @ P @ v)**2))\n        print(f\"n={n}: sigma_x*sigma_p = {sx * sp:.5f} hbar (expect {n + 0.5})\")\n";

export const ML_LADDER = "%% Week 3 - Creation & Annihilation Operators (number-basis matrices)\n%  Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n%  a|n> = sqrt(n)|n-1>, a'|n> = sqrt(n+1)|n+1>, [a,a'] = 1, H = a'a + 1/2\nclear; clc;\n\nN = 30;\na = diag(sqrt(1:N-1), 1);       % annihilation\nad = a';                        % creation\n\n% [a, a'] = 1 (exact except truncation corner)\ncomm = a*ad - ad*a;\nbulk = comm(1:N-1, 1:N-1) - eye(N-1);\nfprintf('[a,a''] = 1: max bulk error = %.2e, corner = %+.1f\\n', max(abs(bulk(:))), comm(N,N));\n\n% Hamiltonian eigenvalues (n + 1/2)\nH = ad*a + 0.5*eye(N);\nev = sort(eig(H));\nfprintf('First 6 eigenvalues of H/hbar*omega: '); fprintf('%.1f ', ev(1:6)); fprintf('\\n');\n\n% X, P and [X,P] = i\nX = (a + ad)/sqrt(2); P = 1i*(ad - a)/sqrt(2);\ncommXP = X*P - P*X;\nfprintf('Im<0|[X,P]|0> = %.6f (expect 1)\\n', imag(commXP(1,1)));\n\n% Matrix elements <n-1|a|n> = sqrt(n)\nda = diag(a, 1);\nfprintf('<n-1|a|n> for n=1..5: '); fprintf('%.4f ', da(1:5)); fprintf('\\n');\n\n% Uncertainty product in |n>: sigma_x sigma_p = (n + 1/2) hbar\nfor n = [0 1 4]\n    v = zeros(N,1); v(n+1) = 1;\n    sx = sqrt(v'*(X*X)*v - (v'*X*v)^2);\n    sp = sqrt(real(v'*(P*P)*v - (v'*P*v)^2));\n    fprintf('n=%d: sigma_x*sigma_p = %.5f hbar (expect %.1f)\\n', n, real(sx*sp), n+0.5);\nend\n\n% Heatmap of |<m|a'|n>|\nfigure; imagesc(abs(ad(1:8,1:8))); colorbar; axis square;\ntitle('|<m|a^{\\dagger}|n>| (first 8x8)'); xlabel('n'); ylabel('m');\n";

export const JL_LADDER = "# Week 3 - Creation & Annihilation Operators (number-basis matrices)\n# Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n# a|n> = sqrt(n)|n-1>, a'|n> = sqrt(n+1)|n+1>, [a,a'] = 1, H = a'a + 1/2\nusing LinearAlgebra, Printf\n\nN = 30\na = diagm(1 => sqrt.(1.0:N-1))     # annihilation\nad = collect(a')                   # creation\n\n# [a, a'] = 1 (exact except truncation corner)\ncomm = a * ad - ad * a\nbulk = comm[1:N-1, 1:N-1] - I\n@printf(\"[a,a'] = 1: max bulk error = %.2e, corner = %+.1f\\n\", maximum(abs.(bulk)), comm[N, N])\n\n# Hamiltonian eigenvalues (n + 1/2)\nH = ad * a + 0.5 * Matrix{Float64}(I, N, N)\nev = sort(eigvals(Symmetric(H)))\nprintln(\"First 6 eigenvalues of H/hbar*omega: \", round.(ev[1:6]; digits = 6))\n\n# X, P and [X,P] = i\nX = (a + ad) / sqrt(2)\nP = im .* (ad - a) / sqrt(2)\ncommXP = X * P - P * X\n@printf(\"Im<0|[X,P]|0> = %.6f (expect 1)\\n\", imag(commXP[1, 1]))\n\n# Matrix elements <n-1|a|n> = sqrt(n)\nprintln(\"<n-1|a|n> for n=1..5: \", [round(a[n, n + 1]; digits = 4) for n in 1:5])\n\n# Uncertainty product in |n>: sigma_x sigma_p = (n + 1/2) hbar\nfor n in (0, 1, 4)\n    v = zeros(N); v[n + 1] = 1.0\n    sx = sqrt(v' * (X * X) * v - (v' * X * v)^2)\n    sp = sqrt(real(v' * (P * P) * v - (v' * P * v)^2))\n    @printf(\"n=%d: sigma_x*sigma_p = %.5f hbar (expect %.1f)\\n\", n, real(sx * sp), n + 0.5)\nend\n";

export const CPP_LADDER = "// Week 3 - Creation & Annihilation Operators (number-basis matrices)\n// Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n// a|n> = sqrt(n)|n-1>, a'|n> = sqrt(n+1)|n+1>, [a,a'] = 1, H = a'a + 1/2\n// Build: g++ -O2 -std=c++17 wk03_ladder.cpp -o wk03_ladder\n#include <cstdio>\n#include <cmath>\n#include <complex>\n#include <vector>\n\nusing cd = std::complex<double>;\nusing Mat = std::vector<std::vector<cd>>;\n\nMat zeros(int N) { return Mat(N, std::vector<cd>(N, 0.0)); }\n\nMat mul(const Mat& A, const Mat& B) {\n    int N = (int)A.size();\n    Mat C = zeros(N);\n    for (int i = 0; i < N; ++i)\n        for (int k = 0; k < N; ++k) {\n            cd a = A[i][k];\n            if (a == cd(0.0)) continue;\n            for (int j = 0; j < N; ++j) C[i][j] += a * B[k][j];\n        }\n    return C;\n}\n\nMat sub(const Mat& A, const Mat& B) {\n    int N = (int)A.size(); Mat C = zeros(N);\n    for (int i = 0; i < N; ++i) for (int j = 0; j < N; ++j) C[i][j] = A[i][j] - B[i][j];\n    return C;\n}\n\nint main() {\n    const int N = 30;\n    Mat a = zeros(N), ad = zeros(N);\n    for (int n = 1; n < N; ++n) {                 // <n-1|a|n> = sqrt(n)\n        a[n - 1][n] = std::sqrt((double)n);\n        ad[n][n - 1] = std::sqrt((double)n);\n    }\n\n    // 1) [a, a'] = 1 (exact except truncation corner)\n    Mat comm = sub(mul(a, ad), mul(ad, a));\n    double bulkErr = 0.0;\n    for (int i = 0; i < N - 1; ++i)\n        for (int j = 0; j < N - 1; ++j)\n            bulkErr = std::max(bulkErr, std::abs(comm[i][j] - (i == j ? cd(1.0) : cd(0.0))));\n    std::printf(\"[a,a'] = 1: max bulk error = %.2e, corner = %+.1f\\n\",\n                bulkErr, comm[N - 1][N - 1].real());\n\n    // 2) H = a'a + 1/2: diagonal in the number basis -> read eigenvalues directly\n    Mat H = mul(ad, a);\n    std::printf(\"First 6 eigenvalues of H/hbar*omega:\");\n    for (int n = 0; n < 6; ++n) std::printf(\" %.1f\", H[n][n].real() + 0.5);\n    std::printf(\"\\n\");\n\n    // 3) X, P and [X,P] = i\n    Mat X = zeros(N), P = zeros(N);\n    const double s2 = std::sqrt(2.0);\n    for (int i = 0; i < N; ++i)\n        for (int j = 0; j < N; ++j) {\n            X[i][j] = (a[i][j] + ad[i][j]) / s2;\n            P[i][j] = cd(0.0, 1.0) * (ad[i][j] - a[i][j]) / s2;\n        }\n    Mat cXP = sub(mul(X, P), mul(P, X));\n    std::printf(\"Im<0|[X,P]|0> = %.6f (expect 1)\\n\", cXP[0][0].imag());\n\n    // 4) Matrix elements <n-1|a|n> = sqrt(n)\n    std::printf(\"<n-1|a|n> for n=1..5:\");\n    for (int n = 1; n <= 5; ++n) std::printf(\" %.4f\", a[n - 1][n].real());\n    std::printf(\"\\n\");\n\n    // 5) Uncertainty product in |n>: sigma_x sigma_p = (n + 1/2) hbar\n    Mat XX = mul(X, X), PP = mul(P, P);\n    for (int n : {0, 1, 4}) {\n        double sx = std::sqrt(XX[n][n].real());   // <n|X|n> = 0\n        double sp = std::sqrt(PP[n][n].real());   // <n|P|n> = 0\n        std::printf(\"n=%d: sigma_x*sigma_p = %.5f hbar (expect %.1f)\\n\", n, sx * sp, n + 0.5);\n    }\n    return 0;\n}\n";

export const PY_ANGMOM = "\"\"\"\nWeek 3 - Angular Momentum Operators & Ladder Operators\nPhysical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n\nBuilds Lz, L+, L-, Lx, Ly, L^2 as (2l+1)x(2l+1) matrices in the |l,m> basis\n(hbar = 1) and verifies:\n  [Lx, Ly] = i Lz (cyclic),  [L^2, Lz] = 0,\n  L^2 = l(l+1) * Identity,\n  L+|l,m> = sqrt((l-m)(l+m+1)) |l,m+1>,\n  b_max = l, b_min = -l (ladder termination),\nand the generalized uncertainty  sigma_Lx * sigma_Ly >= |<Lz>|/2.\n\"\"\"\nimport numpy as np\n\ndef angmom_ops(l):\n    \"\"\"Return (Lx, Ly, Lz, Lp, Lm, L2) in the basis m = l, l-1, ..., -l.\"\"\"\n    dim = int(round(2 * l)) + 1\n    ms = np.array([l - k for k in range(dim)], dtype=float)\n    Lz = np.diag(ms)\n    Lp = np.zeros((dim, dim))\n    for k in range(1, dim):            # raises m: |l, m> -> |l, m+1>\n        m = ms[k]\n        Lp[k - 1, k] = np.sqrt(l * (l + 1) - m * (m + 1))\n    Lm = Lp.T.copy()\n    Lx = 0.5 * (Lp + Lm)\n    Ly = -0.5j * (Lp - Lm)\n    L2 = Lx @ Lx + Ly @ Ly + Lz @ Lz\n    return Lx, Ly, Lz, Lp, Lm, L2\n\nif __name__ == \"__main__\":\n    for l in [1, 2]:\n        Lx, Ly, Lz, Lp, Lm, L2 = angmom_ops(l)\n        dim = Lz.shape[0]\n        I = np.eye(dim)\n        e1 = np.max(np.abs(Lx @ Ly - Ly @ Lx - 1j * Lz))   # [Lx,Ly] = i Lz\n        e2 = np.max(np.abs(L2 @ Lz - Lz @ L2))             # [L^2,Lz] = 0\n        e3 = np.max(np.abs(L2 - l * (l + 1) * I))          # L^2 = l(l+1) I\n        print(f\"l={l}: |[Lx,Ly]-iLz| = {e1:.2e},  |[L2,Lz]| = {e2:.2e},  |L2 - l(l+1)I| = {e3:.2e}\")\n\n    # Ladder coefficients for l = 2: c+(l,m) = sqrt((l-m)(l+m+1))\n    l = 2\n    _, _, _, Lp, Lm, _ = angmom_ops(l)\n    print(\"c+(2,m) for m = 1, 0, -1, -2:\",\n          [f\"{Lp[k - 1, k]:.4f}\" for k in range(1, 5)],\n          \"  (exact: sqrt(4), sqrt(6), sqrt(6), sqrt(4) reversed order in m)\")\n\n    # Ladder termination: L+|l,l> = 0, L-|l,-l> = 0\n    top = np.zeros(5); top[0] = 1.0     # |2, +2>\n    bot = np.zeros(5); bot[-1] = 1.0    # |2, -2>\n    print(f\"|L+|2,+2>| = {np.linalg.norm(Lp @ top):.1e},  |L-|2,-2>| = {np.linalg.norm(Lm @ bot):.1e}\")\n\n    # Generalized uncertainty in |l=1, m=1>: sigma_Lx sigma_Ly >= |<Lz>|/2\n    Lx, Ly, Lz, _, _, _ = angmom_ops(1)\n    v = np.array([1.0, 0.0, 0.0])       # |1, +1>\n    sx = np.sqrt(np.real(v @ (Lx @ Lx) @ v) - np.real(v @ Lx @ v)**2)\n    sy = np.sqrt(np.real(v @ (Ly @ Ly) @ v) - np.real(v @ Ly @ v)**2)\n    print(f\"|1,+1>: sigma_Lx*sigma_Ly = {sx * sy:.4f} >= |<Lz>|/2 = {abs(np.real(v @ Lz @ v)) / 2:.4f}\")\n\n    # Vector model: |L| = sqrt(l(l+1)), cone half-angle for each m (l = 2)\n    L = np.sqrt(2 * 3.0)\n    for m in [2, 1, 0, -1, -2]:\n        theta = np.degrees(np.arccos(m / L))\n        print(f\"l=2, m={m:+d}: |L| = sqrt(6) = {L:.4f} hbar, cone angle = {theta:.2f} deg\")\n";

export const ML_ANGMOM = "%% Week 3 - Angular Momentum & Ladder Operators (|l,m> basis, hbar = 1)\n%  Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n%  [Lx,Ly] = i Lz, [L^2,Lz] = 0, L^2 = l(l+1) I, L+|l,m> = c+(l,m)|l,m+1>\nclear; clc;\n\nfor l = [1 2]\n    [Lx, Ly, Lz, Lp, Lm, L2] = angmom(l);\n    d = 2*l + 1; I = eye(d);\n    e1 = max(abs(Lx*Ly - Ly*Lx - 1i*Lz), [], 'all');\n    e2 = max(abs(L2*Lz - Lz*L2), [], 'all');\n    e3 = max(abs(L2 - l*(l+1)*I), [], 'all');\n    fprintf('l=%d: |[Lx,Ly]-iLz| = %.2e, |[L2,Lz]| = %.2e, |L2-l(l+1)I| = %.2e\\n', l, e1, e2, e3);\nend\n\n% Ladder termination for l = 2\n[~, ~, ~, Lp, Lm, ~] = angmom(2);\ntop = [1;0;0;0;0]; bot = [0;0;0;0;1];\nfprintf('|L+|2,+2>| = %.1e, |L-|2,-2>| = %.1e\\n', norm(Lp*top), norm(Lm*bot));\n\n% Generalized uncertainty in |1,+1>: sigma_Lx sigma_Ly >= |<Lz>|/2\n[Lx, Ly, Lz] = angmom(1);\nv = [1;0;0];\nsx = sqrt(real(v'*(Lx*Lx)*v) - real(v'*Lx*v)^2);\nsy = sqrt(real(v'*(Ly*Ly)*v) - real(v'*Ly*v)^2);\nfprintf('|1,+1>: sLx*sLy = %.4f >= |<Lz>|/2 = %.4f\\n', sx*sy, abs(real(v'*Lz*v))/2);\n\n% Vector model: cone angles for l = 2\nL = sqrt(2*3);\nfor m = 2:-1:-2\n    fprintf('l=2, m=%+d: cone angle = %.2f deg\\n', m, acosd(m/L));\nend\n\nfunction [Lx, Ly, Lz, Lp, Lm, L2] = angmom(l)\n% Matrices in basis m = l, l-1, ..., -l\n    d = 2*l + 1;\n    ms = l:-1:-l;\n    Lz = diag(ms);\n    Lp = zeros(d);\n    for k = 2:d\n        m = ms(k);\n        Lp(k-1, k) = sqrt(l*(l+1) - m*(m+1));\n    end\n    Lm = Lp';\n    Lx = (Lp + Lm)/2; Ly = (Lp - Lm)/(2i);\n    L2 = Lx*Lx + Ly*Ly + Lz*Lz;\nend\n";

export const JL_ANGMOM = "# Week 3 - Angular Momentum & Ladder Operators (|l,m> basis, hbar = 1)\n# Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n# [Lx,Ly] = i Lz, [L^2,Lz] = 0, L^2 = l(l+1) I, L+|l,m> = c+(l,m)|l,m+1>\nusing LinearAlgebra, Printf\n\n\"Return (Lx, Ly, Lz, Lp, Lm, L2) in basis m = l, l-1, ..., -l\"\nfunction angmom(l)\n    d = 2l + 1\n    ms = collect(l:-1:-l) .* 1.0\n    Lz = diagm(ms)\n    Lp = zeros(d, d)\n    for k in 2:d\n        m = ms[k]\n        Lp[k - 1, k] = sqrt(l * (l + 1) - m * (m + 1))\n    end\n    Lm = collect(Lp')\n    Lx = (Lp + Lm) / 2\n    Ly = (Lp - Lm) / (2im)\n    L2 = Lx * Lx + Ly * Ly + Lz * Lz\n    return Lx, Ly, Lz, Lp, Lm, L2\nend\n\nfor l in (1, 2)\n    Lx, Ly, Lz, Lp, Lm, L2 = angmom(l)\n    d = 2l + 1\n    e1 = maximum(abs.(Lx * Ly - Ly * Lx - im * Lz))\n    e2 = maximum(abs.(L2 * Lz - Lz * L2))\n    e3 = maximum(abs.(L2 - l * (l + 1) * I))\n    @printf(\"l=%d: |[Lx,Ly]-iLz| = %.2e, |[L2,Lz]| = %.2e, |L2-l(l+1)I| = %.2e\\n\", l, e1, e2, e3)\nend\n\n# Ladder termination for l = 2\n_, _, _, Lp, Lm, _ = angmom(2)\ntop = [1.0, 0, 0, 0, 0]; bot = [0, 0, 0, 0, 1.0]\n@printf(\"|L+|2,+2>| = %.1e, |L-|2,-2>| = %.1e\\n\", norm(Lp * top), norm(Lm * bot))\n\n# Generalized uncertainty in |1,+1>: sigma_Lx sigma_Ly >= |<Lz>|/2\nLx, Ly, Lz, _, _, _ = angmom(1)\nv = [1.0, 0, 0]\nsx = sqrt(real(v' * (Lx * Lx) * v) - real(v' * Lx * v)^2)\nsy = sqrt(real(v' * (Ly * Ly) * v) - real(v' * Ly * v)^2)\n@printf(\"|1,+1>: sLx*sLy = %.4f >= |<Lz>|/2 = %.4f\\n\", sx * sy, abs(real(v' * Lz * v)) / 2)\n\n# Vector model: cone angles for l = 2\nL = sqrt(2 * 3)\nfor m in 2:-1:-2\n    @printf(\"l=2, m=%+d: cone angle = %.2f deg\\n\", m, acosd(m / L))\nend\n";

export const CPP_ANGMOM = "// Week 3 - Angular Momentum & Ladder Operators (|l,m> basis, hbar = 1)\n// Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n// [Lx,Ly] = i Lz, [L^2,Lz] = 0, L^2 = l(l+1) I, L+|l,m> = c+(l,m)|l,m+1>\n// Build: g++ -O2 -std=c++17 wk03_angmom.cpp -o wk03_angmom\n#include <cstdio>\n#include <cmath>\n#include <complex>\n#include <vector>\n\nusing cd = std::complex<double>;\nusing Mat = std::vector<std::vector<cd>>;\n\nMat zeros(int d) { return Mat(d, std::vector<cd>(d, 0.0)); }\n\nMat mul(const Mat& A, const Mat& B) {\n    int d = (int)A.size(); Mat C = zeros(d);\n    for (int i = 0; i < d; ++i)\n        for (int k = 0; k < d; ++k)\n            for (int j = 0; j < d; ++j) C[i][j] += A[i][k] * B[k][j];\n    return C;\n}\n\nMat sub(const Mat& A, const Mat& B) {\n    int d = (int)A.size(); Mat C = zeros(d);\n    for (int i = 0; i < d; ++i) for (int j = 0; j < d; ++j) C[i][j] = A[i][j] - B[i][j];\n    return C;\n}\n\ndouble maxAbs(const Mat& A) {\n    double m = 0; for (auto& r : A) for (auto& v : r) m = std::max(m, std::abs(v));\n    return m;\n}\n\nstruct AngMom { Mat Lx, Ly, Lz, Lp, Lm, L2; int d; };\n\nAngMom angmom(int l) {                        // basis m = l, l-1, ..., -l\n    int d = 2 * l + 1;\n    AngMom A{zeros(d), zeros(d), zeros(d), zeros(d), zeros(d), zeros(d), d};\n    for (int k = 0; k < d; ++k) A.Lz[k][k] = (double)(l - k);\n    for (int k = 1; k < d; ++k) {\n        double m = (double)(l - k);\n        A.Lp[k - 1][k] = std::sqrt(l * (l + 1.0) - m * (m + 1.0));   // raises m\n        A.Lm[k][k - 1] = A.Lp[k - 1][k].real();                      // = (L+)^T\n    }\n    for (int i = 0; i < d; ++i)\n        for (int j = 0; j < d; ++j) {\n            A.Lx[i][j] = 0.5 * (A.Lp[i][j] + A.Lm[i][j]);\n            A.Ly[i][j] = cd(0.0, -0.5) * (A.Lp[i][j] - A.Lm[i][j]);\n        }\n    Mat t = mul(A.Lx, A.Lx), u = mul(A.Ly, A.Ly), w = mul(A.Lz, A.Lz);\n    for (int i = 0; i < d; ++i)\n        for (int j = 0; j < d; ++j) A.L2[i][j] = t[i][j] + u[i][j] + w[i][j];\n    return A;\n}\n\nint main() {\n    for (int l : {1, 2}) {\n        AngMom A = angmom(l);\n        Mat c1 = sub(mul(A.Lx, A.Ly), mul(A.Ly, A.Lx));   // should equal i Lz\n        for (int i = 0; i < A.d; ++i)\n            for (int j = 0; j < A.d; ++j) c1[i][j] -= cd(0.0, 1.0) * A.Lz[i][j];\n        Mat c2 = sub(mul(A.L2, A.Lz), mul(A.Lz, A.L2));\n        Mat c3 = A.L2;\n        for (int i = 0; i < A.d; ++i) c3[i][i] -= (double)(l * (l + 1));\n        std::printf(\"l=%d: |[Lx,Ly]-iLz| = %.2e, |[L2,Lz]| = %.2e, |L2-l(l+1)I| = %.2e\\n\",\n                    l, maxAbs(c1), maxAbs(c2), maxAbs(c3));\n    }\n\n    // Ladder coefficients & termination for l = 2\n    AngMom A = angmom(2);\n    std::printf(\"c+(2,m) matrix elements:\");\n    for (int k = 1; k < A.d; ++k) std::printf(\" %.4f\", A.Lp[k - 1][k].real());\n    std::printf(\"\\nL+|2,+2> column norm = %.1e (termination)\\n\", std::abs(A.Lp[0][0]));\n\n    // Vector model: |L| = sqrt(l(l+1)), cone angles for l = 2\n    double L = std::sqrt(6.0);\n    for (int m = 2; m >= -2; --m)\n        std::printf(\"l=2, m=%+d: cone angle = %.2f deg\\n\", m,\n                    std::acos(m / L) * 180.0 / M_PI);\n    return 0;\n}\n";

export const PY_HYDROGEN = "\"\"\"\nWeek 3 - Spherical Harmonics & the Hydrogen Atom\nPhysical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n\nSpherical harmonics Y_l^m(theta, phi) and hydrogen radial functions\nR_nl(r) (in Bohr radii, a0 = 1), with:\n  psi_nlm = R_nl(r) Y_l^m(theta, phi),  E_n = -13.6057 / n^2 eV.\nVerifies: Y_l^m orthonormality on the sphere, R_nl normalization\nint |R_nl|^2 r^2 dr = 1, <r>_1s = 1.5 a0, most-probable r_1s = a0,\nand the virial theorem <V> = 2E.\n\"\"\"\nimport numpy as np\nfrom math import factorial, pi, sqrt\n\ntrapz = getattr(np, \"trapezoid\", getattr(np, \"trapz\", None))  # numpy 1.x/2.x compat\n\ndef assoc_legendre(l, m, x):\n    \"\"\"Associated Legendre P_l^m(x) (m >= 0) via stable recurrences.\"\"\"\n    m = abs(m)\n    Pmm = np.ones_like(x)\n    if m > 0:\n        somx2 = np.sqrt((1.0 - x) * (1.0 + x))\n        fact = 1.0\n        for _ in range(m):\n            Pmm *= -fact * somx2\n            fact += 2.0\n    if l == m: return Pmm\n    Pm1 = x * (2 * m + 1) * Pmm\n    if l == m + 1: return Pm1\n    for ll in range(m + 2, l + 1):\n        Pll = (x * (2 * ll - 1) * Pm1 - (ll + m - 1) * Pmm) / (ll - m)\n        Pmm, Pm1 = Pm1, Pll\n    return Pm1\n\ndef Ylm(l, m, theta, phi):\n    \"\"\"Complex spherical harmonic (Condon-Shortley phase).\"\"\"\n    N = sqrt((2 * l + 1) / (4 * pi) * factorial(l - abs(m)) / factorial(l + abs(m)))\n    P = assoc_legendre(l, m, np.cos(theta))\n    Y = N * P * np.exp(1j * abs(m) * phi)\n    if m < 0:\n        Y = (-1.0) ** m * np.conj(Y)\n    return Y\n\ndef laguerre(k, alpha, x):\n    \"\"\"Associated (generalized) Laguerre polynomial L_k^{(alpha)}(x) by recurrence.\"\"\"\n    if k == 0: return np.ones_like(x)\n    Lm, Lc = np.ones_like(x), 1.0 + alpha - x\n    for i in range(1, k):\n        Lm, Lc = Lc, ((2 * i + 1 + alpha - x) * Lc - (i + alpha) * Lm) / (i + 1)\n    return Lc\n\ndef R_nl(n, l, r):\n    \"\"\"Hydrogen radial function (a0 = 1): R_nl = N rho^l e^{-rho/2} L_{n-l-1}^{(2l+1)}(rho), rho = 2r/n.\"\"\"\n    rho = 2.0 * r / n\n    N = sqrt((2.0 / n) ** 3 * factorial(n - l - 1) / (2.0 * n * factorial(n + l)))\n    return N * rho ** l * np.exp(-rho / 2.0) * laguerre(n - l - 1, 2 * l + 1, rho)\n\nif __name__ == \"__main__\":\n    # 1) Y_l^m orthonormality: <l'm'|lm> over the sphere\n    th = np.linspace(0, pi, 1201); ph = np.linspace(0, 2 * pi, 1201)\n    TH, PH = np.meshgrid(th, ph, indexing=\"ij\")\n    dOm = np.sin(TH)\n    def inner(l1, m1, l2, m2):\n        f = np.conj(Ylm(l1, m1, TH, PH)) * Ylm(l2, m2, TH, PH) * dOm\n        return trapz(trapz(f, ph, axis=1), th)\n    print(f\"<Y_0^0|Y_0^0> = {inner(0,0,0,0).real:.6f}\")\n    print(f\"<Y_1^0|Y_1^0> = {inner(1,0,1,0).real:.6f}, <Y_2^1|Y_2^1> = {inner(2,1,2,1).real:.6f}\")\n    print(f\"<Y_1^0|Y_2^0> = {inner(1,0,2,0).real:+.2e}, <Y_1^1|Y_1^-1> = {abs(inner(1,1,1,-1)):.2e}\")\n\n    # 2) Radial normalization: int R_nl^2 r^2 dr = 1\n    r = np.linspace(1e-8, 120, 400001)\n    for (n, l) in [(1, 0), (2, 0), (2, 1), (3, 2)]:\n        I = trapz(R_nl(n, l, r) ** 2 * r ** 2, r)\n        print(f\"int R_{n}{l}^2 r^2 dr = {I:.6f}\")\n\n    # 3) <r>_1s = 1.5 a0, most probable r = a0\n    P1s = R_nl(1, 0, r) ** 2 * r ** 2\n    print(f\"<r>_1s = {trapz(r * P1s, r):.5f} a0 (exact 1.5), r_mp = {r[np.argmax(P1s)]:.4f} a0 (exact 1)\")\n\n    # 4) Energy levels E_n = -13.6057 / n^2 eV and virial <V> = 2E\n    Ry = 13.605693\n    for n in [1, 2, 3]:\n        print(f\"E_{n} = {-Ry / n**2:.4f} eV\")\n    Vexp = trapz(-1.0 / r * P1s, r)          # <V> in Hartree = <-1/r>\n    print(f\"<V>_1s = {Vexp:.5f} Ha = 2*E_1 = {2 * (-0.5):.5f} Ha (virial)\")\n\n    # 5) Degeneracy without spin: sum_{l=0}^{n-1} (2l+1) = n^2\n    for n in [1, 2, 3, 4]:\n        print(f\"n={n}: degeneracy = {sum(2 * l + 1 for l in range(n))} = n^2 = {n**2}\")\n";

export const ML_HYDROGEN = "%% Week 3 - Spherical Harmonics & the Hydrogen Atom (a0 = 1)\n%  Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n%  psi_nlm = R_nl(r) Y_l^m(theta,phi), E_n = -13.6057/n^2 eV\nclear; clc;\n\n% Y_l^m orthonormality on the sphere (via legendre + explicit norm)\nth = linspace(0, pi, 1201); ph = linspace(0, 2*pi, 1201);\n[TH, PH] = ndgrid(th, ph);\nfprintf('<Y_1^0|Y_1^0> = %.6f\\n', real(innerY(1,0,1,0,TH,PH,th,ph)));\nfprintf('<Y_2^1|Y_2^1> = %.6f\\n', real(innerY(2,1,2,1,TH,PH,th,ph)));\nfprintf('<Y_1^0|Y_2^0> = %+.2e\\n', real(innerY(1,0,2,0,TH,PH,th,ph)));\n\n% Radial normalization: int R_nl^2 r^2 dr = 1\nr = linspace(1e-8, 120, 400001);\npairs = [1 0; 2 0; 2 1; 3 2];\nfor k = 1:size(pairs,1)\n    n = pairs(k,1); l = pairs(k,2);\n    I = trapz(r, Rnl(n,l,r).^2.*r.^2);\n    fprintf('int R_%d%d^2 r^2 dr = %.6f\\n', n, l, I);\nend\n\n% <r>_1s = 1.5 a0, most probable r = a0, virial <V> = 2E\nP1s = Rnl(1,0,r).^2.*r.^2;\n[~, im] = max(P1s);\nfprintf('<r>_1s = %.5f a0, r_mp = %.4f a0\\n', trapz(r, r.*P1s), r(im));\nfprintf('<V>_1s = %.5f Ha (= 2E_1 = -1)\\n', trapz(r, -1./r.*P1s));\n\n% Energy levels\nRy = 13.605693;\nfor n = 1:3, fprintf('E_%d = %.4f eV\\n', n, -Ry/n^2); end\n\n% Radial functions plot\nfigure; hold on;\nrr = linspace(0, 25, 1001);\nplot(rr, Rnl(1,0,rr), rr, Rnl(2,0,rr), rr, Rnl(2,1,rr), rr, Rnl(3,0,rr), 'LineWidth', 1.4);\nlegend('R_{10}','R_{20}','R_{21}','R_{30}'); xlabel('r/a_0'); ylabel('R_{nl}'); grid on;\n\nfunction I = innerY(l1,m1,l2,m2,TH,PH,th,ph)\n    f = conj(Ylm(l1,m1,TH,PH)).*Ylm(l2,m2,TH,PH).*sin(TH);\n    I = trapz(th, trapz(ph, f, 2));\nend\n\nfunction Y = Ylm(l, m, TH, PH)\n% Complex spherical harmonic with Condon-Shortley phase\n    am = abs(m);\n    P = legendre(l, cos(TH(:,1)));       % (l+1) x length(th), includes C-S phase\n    Pl = P(am+1, :).';                   % column over theta\n    N = sqrt((2*l+1)/(4*pi)*factorial(l-am)/factorial(l+am));\n    Y = N*(Pl*ones(1,size(TH,2))).*exp(1i*am*PH);\n    if m < 0, Y = (-1)^m*conj(Y); end\nend\n\nfunction R = Rnl(n, l, r)\n% Hydrogen radial function via associated Laguerre recurrence (a0 = 1)\n    rho = 2*r/n;\n    N = sqrt((2/n)^3*factorial(n-l-1)/(2*n*factorial(n+l)));\n    R = N.*rho.^l.*exp(-rho/2).*laguerreL_rec(n-l-1, 2*l+1, rho);\nend\n\nfunction L = laguerreL_rec(k, alpha, x)\n    if k == 0, L = ones(size(x)); return; end\n    Lm = ones(size(x)); Lc = 1 + alpha - x;\n    for i = 1:k-1\n        Ln = ((2*i+1+alpha-x).*Lc - (i+alpha)*Lm)/(i+1);\n        Lm = Lc; Lc = Ln;\n    end\n    L = Lc;\nend\n";

export const JL_HYDROGEN = "# Week 3 - Spherical Harmonics & the Hydrogen Atom (a0 = 1)\n# Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n# psi_nlm = R_nl(r) Y_l^m(theta,phi), E_n = -13.6057/n^2 eV\nusing Printf\n\ntrapz(x, f) = sum((f[1:end-1] .+ f[2:end]) .* diff(x)) / 2\n\n\"Associated Legendre P_l^m(x) (m >= 0, Condon-Shortley) via stable recurrences\"\nfunction assoc_legendre(l, m, x)\n    Pmm = one.(x)\n    if m > 0\n        somx2 = sqrt.((1 .- x) .* (1 .+ x))\n        fact = 1.0\n        for _ in 1:m\n            Pmm = Pmm .* (-fact) .* somx2\n            fact += 2\n        end\n    end\n    l == m && return Pmm\n    Pm1 = x .* (2m + 1) .* Pmm\n    l == m + 1 && return Pm1\n    local Pll\n    for ll in (m + 2):l\n        Pll = (x .* (2ll - 1) .* Pm1 .- (ll + m - 1) .* Pmm) ./ (ll - m)\n        Pmm, Pm1 = Pm1, Pll\n    end\n    return Pm1\nend\n\n\"Complex spherical harmonic Y_l^m\"\nfunction Ylm(l, m, theta, phi)\n    am = abs(m)\n    N = sqrt((2l + 1) / (4pi) * factorial(l - am) / factorial(l + am))\n    Y = N .* assoc_legendre(l, am, cos.(theta)) .* exp.(im * am .* phi)\n    m < 0 && (Y = (-1)^m .* conj.(Y))\n    return Y\nend\n\n\"Associated Laguerre L_k^(alpha)(x) by recurrence\"\nfunction laguerreL(k, alpha, x)\n    k == 0 && return one.(x)\n    Lm, Lc = one.(x), 1 .+ alpha .- x\n    for i in 1:k-1\n        Lm, Lc = Lc, ((2i + 1 + alpha .- x) .* Lc .- (i + alpha) .* Lm) ./ (i + 1)\n    end\n    return Lc\nend\n\n\"Hydrogen radial function (a0 = 1)\"\nfunction Rnl(n, l, r)\n    rho = 2 .* r ./ n\n    N = sqrt((2 / n)^3 * factorial(n - l - 1) / (2n * factorial(n + l)))\n    return N .* rho .^ l .* exp.(-rho ./ 2) .* laguerreL(n - l - 1, 2l + 1, rho)\nend\n\n# 1) Y_l^m orthonormality on the sphere\nth = range(0, pi; length = 1201) |> collect\nph = range(0, 2pi; length = 1201) |> collect\nfunction innerY(l1, m1, l2, m2)\n    g = [conj(Ylm(l1, m1, t, p)) * Ylm(l2, m2, t, p) * sin(t) for t in th, p in ph]\n    rowint = [trapz(ph, g[i, :]) for i in eachindex(th)]\n    return trapz(th, rowint)\nend\n@printf(\"<Y_1^0|Y_1^0> = %.6f\\n\", real(innerY(1, 0, 1, 0)))\n@printf(\"<Y_2^1|Y_2^1> = %.6f\\n\", real(innerY(2, 1, 2, 1)))\n@printf(\"<Y_1^0|Y_2^0> = %+.2e\\n\", real(innerY(1, 0, 2, 0)))\n\n# 2) Radial normalization, <r>_1s, virial\nr = range(1e-8, 120; length = 400001) |> collect\nfor (n, l) in ((1, 0), (2, 0), (2, 1), (3, 2))\n    I = trapz(r, Rnl(n, l, r) .^ 2 .* r .^ 2)\n    @printf(\"int R_%d%d^2 r^2 dr = %.6f\\n\", n, l, I)\nend\nP1s = Rnl(1, 0, r) .^ 2 .* r .^ 2\n@printf(\"<r>_1s = %.5f a0, r_mp = %.4f a0\\n\", trapz(r, r .* P1s), r[argmax(P1s)])\n@printf(\"<V>_1s = %.5f Ha (= 2E_1 = -1)\\n\", trapz(r, -1 ./ r .* P1s))\n\n# 3) Energy levels & degeneracy\nRy = 13.605693\nfor n in 1:3\n    @printf(\"E_%d = %.4f eV\\n\", n, -Ry / n^2)\nend\nfor n in 1:4\n    println(\"n=$n: degeneracy = \", sum(2l + 1 for l in 0:n-1), \" = n^2 = \", n^2)\nend\n";

export const CPP_HYDROGEN = "// Week 3 - Spherical Harmonics & the Hydrogen Atom (a0 = 1)\n// Physical Chemistry 2, SKKU (Prof. S. Joon Kwon)\n// psi_nlm = R_nl(r) Y_l^m(theta,phi), E_n = -13.6057/n^2 eV\n// Build: g++ -O2 -std=c++17 wk03_hydrogen.cpp -o wk03_hydrogen\n#include <cstdio>\n#include <cmath>\n#include <complex>\n#include <vector>\n\nusing cd = std::complex<double>;\n\ndouble factorial(int n) { double f = 1; for (int i = 2; i <= n; ++i) f *= i; return f; }\n\n// Associated Legendre P_l^m(x), m >= 0, Condon-Shortley phase\ndouble assocLegendre(int l, int m, double x) {\n    double Pmm = 1.0;\n    if (m > 0) {\n        double somx2 = std::sqrt((1.0 - x) * (1.0 + x)), fact = 1.0;\n        for (int i = 0; i < m; ++i) { Pmm *= -fact * somx2; fact += 2.0; }\n    }\n    if (l == m) return Pmm;\n    double Pm1 = x * (2 * m + 1) * Pmm;\n    if (l == m + 1) return Pm1;\n    double Pll = 0.0;\n    for (int ll = m + 2; ll <= l; ++ll) {\n        Pll = (x * (2 * ll - 1) * Pm1 - (ll + m - 1) * Pmm) / (ll - m);\n        Pmm = Pm1; Pm1 = Pll;\n    }\n    return Pll;\n}\n\ncd Ylm(int l, int m, double theta, double phi) {\n    int am = std::abs(m);\n    double N = std::sqrt((2 * l + 1) / (4.0 * M_PI) * factorial(l - am) / factorial(l + am));\n    cd Y = N * assocLegendre(l, am, std::cos(theta)) * std::exp(cd(0.0, am * phi));\n    if (m < 0) Y = std::pow(-1.0, m) * std::conj(Y);\n    return Y;\n}\n\n// Associated Laguerre L_k^(alpha)(x) by recurrence\ndouble laguerreL(int k, int alpha, double x) {\n    if (k == 0) return 1.0;\n    double Lm = 1.0, Lc = 1.0 + alpha - x;\n    for (int i = 1; i < k; ++i) {\n        double Ln = ((2 * i + 1 + alpha - x) * Lc - (i + alpha) * Lm) / (i + 1);\n        Lm = Lc; Lc = Ln;\n    }\n    return Lc;\n}\n\n// Hydrogen radial function (a0 = 1)\ndouble Rnl(int n, int l, double r) {\n    double rho = 2.0 * r / n;\n    double N = std::sqrt(std::pow(2.0 / n, 3) * factorial(n - l - 1) / (2.0 * n * factorial(n + l)));\n    return N * std::pow(rho, l) * std::exp(-rho / 2.0) * laguerreL(n - l - 1, 2 * l + 1, rho);\n}\n\nint main() {\n    // 1) Y_l^m orthonormality on the sphere (2D trapezoid rule)\n    const int NT = 1200, NP = 1200;\n    auto innerY = [&](int l1, int m1, int l2, int m2) {\n        double dth = M_PI / NT, dph = 2.0 * M_PI / NP;\n        cd sum = 0.0;\n        for (int i = 0; i <= NT; ++i) {\n            double th = i * dth, wt = (i == 0 || i == NT) ? 0.5 : 1.0;\n            cd rowsum = 0.0;\n            for (int j = 0; j <= NP; ++j) {\n                double ph = j * dph, wp = (j == 0 || j == NP) ? 0.5 : 1.0;\n                rowsum += wp * std::conj(Ylm(l1, m1, th, ph)) * Ylm(l2, m2, th, ph);\n            }\n            sum += wt * rowsum * std::sin(th);\n        }\n        return sum * dth * dph;\n    };\n    std::printf(\"<Y_1^0|Y_1^0> = %.6f\\n\", innerY(1, 0, 1, 0).real());\n    std::printf(\"<Y_2^1|Y_2^1> = %.6f\\n\", innerY(2, 1, 2, 1).real());\n    std::printf(\"<Y_1^0|Y_2^0> = %+.2e\\n\", innerY(1, 0, 2, 0).real());\n\n    // 2) Radial normalization: int R_nl^2 r^2 dr = 1  (uniform trapezoid)\n    const double RMAX = 120.0; const int NR = 400000;\n    auto radInt = [&](auto f) {\n        double h = RMAX / NR, s = 0.5 * (f(1e-12) + f(RMAX));\n        for (int i = 1; i < NR; ++i) s += f(i * h);\n        return s * h;\n    };\n    int pairs[4][2] = {{1, 0}, {2, 0}, {2, 1}, {3, 2}};\n    for (auto& p : pairs) {\n        int n = p[0], l = p[1];\n        double I = radInt([&](double r) { double R = Rnl(n, l, r); return R * R * r * r; });\n        std::printf(\"int R_%d%d^2 r^2 dr = %.6f\\n\", n, l, I);\n    }\n\n    // 3) <r>_1s = 1.5 a0, virial <V>_1s = 2 E_1 = -1 Ha\n    double rExp = radInt([&](double r) { double R = Rnl(1, 0, r); return r * R * R * r * r; });\n    double vExp = radInt([&](double r) { double R = Rnl(1, 0, r); return -1.0 / r * R * R * r * r; });\n    std::printf(\"<r>_1s = %.5f a0 (exact 1.5), <V>_1s = %.5f Ha (virial: -1)\\n\", rExp, vExp);\n\n    // 4) Energy levels & degeneracy\n    const double Ry = 13.605693;\n    for (int n = 1; n <= 3; ++n) std::printf(\"E_%d = %.4f eV\\n\", n, -Ry / (n * n));\n    for (int n = 1; n <= 4; ++n) {\n        int g = 0; for (int l = 0; l < n; ++l) g += 2 * l + 1;\n        std::printf(\"n=%d: degeneracy = %d = n^2\\n\", n, g);\n    }\n    return 0;\n}\n";
